bool CoreCurrencyRates::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{

    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }

    if(pJson.isMember("tenant_id"))
    {
        if(!validJsonOfField(1, "tenant_id", pJson["tenant_id"], err, true))
            return false;
    }

    else
    {
        err="The tenant_id column cannot be null";
        return false;
    }

    if(pJson.isMember("accounting_unit_id"))
    {
        if(!validJsonOfField(2, "accounting_unit_id", pJson["accounting_unit_id"], err, true))
            return false;
    }

    else
    {
        err="The accounting_unit_id column cannot be null";
        return false;
    }

    if(pJson.isMember("currency_id"))
    {
        if(!validJsonOfField(3, "currency_id", pJson["currency_id"], err, true))
            return false;
    }

    else
    {
        err="The currency_id column cannot be null";
        return false;
    }

    if(pJson.isMember("rate_type"))
    {
        if(!validJsonOfField(4, "rate_type", pJson["rate_type"], err, true))
            return false;
    }

    if(pJson.isMember("effective_date"))
    {
        if(!validJsonOfField(5, "effective_date", pJson["effective_date"], err, true))
            return false;
    }

    else
    {
        err="The effective_date column cannot be null";
        return false;
    }

    if(pJson.isMember("rate"))
    {
        if(!validJsonOfField(6, "rate", pJson["rate"], err, true))
            return false;
    }

    else
    {
        err="The rate column cannot be null";
        return false;
    }

    if(pJson.isMember("source"))
    {
        if(!validJsonOfField(7, "source", pJson["source"], err, true))
            return false;
    }

    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(8, "created_at", pJson["created_at"], err, true))
            return false;
    }

    if(pJson.isMember("created_by_user_id"))
    {
        if(!validJsonOfField(9, "created_by_user_id", pJson["created_by_user_id"], err, true))
            return false;
    }

    return true;
}
